-- Backfill da carteira Xeque Mate (792 clientes já cadastrados)
-- Atualiza campos detalhados (grupo, cota, valor do crédito, prazo, datas, produto, plano, status financeiro)
-- casando pelos clientes já existentes via numero da proposta. NÃO cria clientes novos.
-- Rode no SQL Editor do Supabase.

begin;

-- Desliga as automações (Fase C/D/F) só durante o backfill, pra não gerar
-- centenas de tarefas de reversão/contemplação por causa de dados históricos.
-- Condicional porque nem todas as migrações de fase podem já ter rodado neste banco.
do $$
begin
  if exists (select 1 from pg_trigger where tgname = 'trg_clientes_after_update_cancelamento' and tgrelid = 'clientes'::regclass) then
    alter table clientes disable trigger trg_clientes_after_update_cancelamento;
  end if;
  if exists (select 1 from pg_trigger where tgname = 'trg_clientes_after_insert' and tgrelid = 'clientes'::regclass) then
    alter table clientes disable trigger trg_clientes_after_insert;
  end if;
  if exists (select 1 from pg_trigger where tgname = 'trg_clientes_after_update_contemplacao' and tgrelid = 'clientes'::regclass) then
    alter table clientes disable trigger trg_clientes_after_update_contemplacao;
  end if;
  if exists (select 1 from pg_trigger where tgname = 'trg_clientes_after_update_auditoria' and tgrelid = 'clientes'::regclass) then
    alter table clientes disable trigger trg_clientes_after_update_auditoria;
  end if;
end $$;

